Replace exactly this text:
"burst_requests": 360
with:
"burst_requests": 480
Change nothing else.

SOURCE BEGIN
{
  "service": "quota-ledger",
  "revision": 3,
  "limits": {
    "burst_requests": 360,
    "sustained_requests": 120,
    "window_seconds": 60
  },
  "storage": {
    "table": "tenant_quota_events",
    "partition_key": "tenant_id",
    "retention_days": 14
  },
  "audit": {
    "enabled": true,
    "include_request_id": true,
    "fields": ["tenant_id", "operation", "result", "duration_ms"]
  }
}
SOURCE END
